#pragma once
#include "PlaybackResidency.h"
// Two source/seek epochs, held in a fixed resident pool. Audio reads only lock-free atomics.
class PlaybackPCMCache {
 static constexpr int stride=64;
 template<int channels,int count> struct Ring {
  struct Cell{std::atomic<uint64_t> sequence{0},mask{0};std::atomic<uintptr_t> source{0};std::atomic<int64_t> first{-1};std::array<std::atomic<float>,channels*stride> samples;};
  std::array<Cell,count> cells;
  static_assert(std::atomic<float>::is_always_lock_free,"PCM cache requires lock-free float loads");
  static constexpr int capacity=count*stride;
  Cell& at(int64_t frame){return cells[(uint64_t)(frame/stride)%count];}
  const Cell& at(int64_t frame)const{return cells[(uint64_t)(frame/stride)%count];}
  bool present(uintptr_t id,int64_t frame)const{if(frame<0)return false;auto& c=at(frame);auto sequence=c.sequence.load(std::memory_order_acquire);if(sequence&1)return false;bool present=c.source.load(std::memory_order_relaxed)==id&&c.first.load(std::memory_order_relaxed)==frame/stride*stride&&(c.mask.load(std::memory_order_relaxed)&(uint64_t(1)<<(frame%stride)));std::atomic_thread_fence(std::memory_order_acq_rel);return present&&c.sequence.load(std::memory_order_acquire)==sequence;}
  bool sample(uintptr_t id,int64_t frame,int channel,float& value)const{if(frame<0)return false;auto& c=at(frame);auto sequence=c.sequence.load(std::memory_order_acquire);if(sequence&1)return false;if(c.source.load(std::memory_order_relaxed)!=id||c.first.load(std::memory_order_relaxed)!=frame/stride*stride||!(c.mask.load(std::memory_order_relaxed)&(uint64_t(1)<<(frame%stride))))return false;value=c.samples[channel*stride+frame%stride].load(std::memory_order_relaxed);std::atomic_thread_fence(std::memory_order_acq_rel);return c.sequence.load(std::memory_order_acquire)==sequence;}
  template<class Reader> void fill(uintptr_t id,double centre,double rate,bool refresh,Reader read){int64_t first=juce::jmax((int64_t)0,(int64_t)std::floor((centre-rate*.1)/stride)*stride),last=(int64_t)std::ceil((centre+juce::jmin(rate,capacity*.65))/stride)*stride;for(int64_t start=first;start<last;start+=stride){auto& c=at(start);bool same=c.source.load()==id&&c.first.load()==start;uint64_t oldMask=same?c.mask.load():0;if(same&&oldMask==~uint64_t(0)&&(!refresh||start<centre+rate*.2))continue;std::array<float,channels*stride> data{};uint64_t mask=0;for(int n=0;n<stride;++n){std::array<float,channels> values{};if(read(start+n,values)){mask|=uint64_t(1)<<n;for(int ch=0;ch<channels;++ch)data[ch*stride+n]=values[ch];}}if(same&&mask==oldMask&&!refresh)continue;c.sequence.fetch_add(1,std::memory_order_acq_rel);c.source.store(id,std::memory_order_relaxed);c.first.store(start,std::memory_order_relaxed);for(size_t n=0;n<data.size();++n)c.samples[n].store(data[n],std::memory_order_relaxed);c.mask.store(mask,std::memory_order_release);c.sequence.fetch_add(1,std::memory_order_release);}}
 };
 struct Bank{Ring<2,2048> dry;Ring<8,1024> live,hq;uintptr_t source=0;double centre=0;const void* liveVersion=nullptr;const void* hqVersion=nullptr;};
 struct Pool{std::array<Bank,2> banks;};
 Pool* pool=nullptr;size_t allocation=0;std::atomic<Pool*> active{nullptr};std::atomic<bool> wired{false};
 template<int channels,int count> bool read(const Ring<channels,count>& ring,uintptr_t id,double point,int channel,float& value,int64_t maximum=INT64_MAX)const{if(point<0)return false;int64_t first=(int64_t)std::floor(point),last=juce::jmin(first+1,maximum);float a=0,b=0;if(!ring.sample(id,first,channel,a))return false;float fraction=(float)(point-first);if(fraction==0||first==last){value=a;return true;}if(!ring.sample(id,last,channel,b))return false;value=a+fraction*(b-a);return true;}
public:
 std::atomic<size_t> failures{0},dryMisses{0};
 bool lock(){if(!pool){allocation=(sizeof(Pool)+PlaybackPageLease::pageSize()-1)/PlaybackPageLease::pageSize()*PlaybackPageLease::pageSize();void* memory=nullptr;if(posix_memalign(&memory,PlaybackPageLease::pageSize(),allocation))return false;pool=new(memory) Pool;}if(!wired){wired=mlock(pool,allocation)==0;if(!wired)++failures;}return wired;}
 void activate(){if(wired)active.store(pool,std::memory_order_release);}bool ready()const{return active.load(std::memory_order_acquire)!=nullptr;}
 size_t bytes()const{return wired?allocation:0;}
 void suspend(){active.store(nullptr,std::memory_order_release);if(wired){munlock(pool,allocation);wired=false;}}
 ~PlaybackPCMCache(){suspend();if(pool){pool->~Pool();free(pool);}}
 int find(const juce::AudioBuffer<float>* source,double point)const{if(!pool)return -1;uintptr_t id=(uintptr_t)source;for(int bank=0;bank<2;++bank)if(pool->banks[bank].source==id&&std::abs(pool->banks[bank].centre-point)<Ring<2,2048>::capacity*.25)return bank;return -1;}
 void fill(int index,const juce::AudioBuffer<float>& source,double rate,double point,std::shared_ptr<const TrackStemWorker::Window> live,std::shared_ptr<const TrackStemWorker::Window> hq){if(!wired)return;auto& bank=pool->banks[index];uintptr_t id=(uintptr_t)&source;bool changed=bank.source!=id;bool newLive=changed||bank.liveVersion!=live.get(),newHQ=changed||bank.hqVersion!=hq.get();bank.dry.fill(id,point,rate,false,[&](int64_t frame,std::array<float,2>& values){if(frame<0||frame>=source.getNumSamples())return false;for(int ch=0;ch<2;++ch)values[ch]=source.getSample(juce::jmin(ch,source.getNumChannels()-1),(int)frame);return true;});auto separated=[&](const auto& window,int64_t frame,std::array<float,8>& values){if(!window||window->source->buffer.get()!=&source)return false;std::array<float,4> left{},right{};if(!window->read(frame,0,left)||!window->read(frame,1,right))return false;for(int stem=0;stem<4;++stem){values[stem*2]=left[stem];values[stem*2+1]=right[stem];}return true;};if(live)bank.live.fill(id,point/rate*44100,44100,newLive,[&](int64_t frame,std::array<float,8>& values){return separated(live,frame,values);});if(hq)bank.hq.fill(id,point/rate*44100,44100,newHQ,[&](int64_t frame,std::array<float,8>& values){return separated(hq,frame,values);});bank.source=id;bank.centre=point;bank.liveVersion=live.get();bank.hqVersion=hq.get();}
 bool dryReady(const juce::AudioBuffer<float>* source,double point,int ahead=1024)const{auto* p=active.load(std::memory_order_acquire);if(!p||!source||source->getNumSamples()==0)return false;int64_t frame=juce::jlimit((int64_t)0,(int64_t)source->getNumSamples()-1,(int64_t)std::floor(point)),last=juce::jmin((int64_t)source->getNumSamples()-1,frame+ahead);for(auto& bank:p->banks)if(bank.dry.present((uintptr_t)source,frame)&&bank.dry.present((uintptr_t)source,last))return true;return false;}
 bool dry(const juce::AudioBuffer<float>* source,double point,int channel,float& value)const{auto* p=active.load(std::memory_order_acquire);if(!p)return false;for(auto& bank:p->banks)if(read(bank.dry,(uintptr_t)source,point,juce::jmin(channel,1),value,source->getNumSamples()-1))return true;return false;}
 bool available(const juce::AudioBuffer<float>* source,double point,bool hq)const{auto* p=active.load(std::memory_order_acquire);if(!p||point<0)return false;for(auto& bank:p->banks){auto& ring=hq?bank.hq:bank.live;if(ring.present((uintptr_t)source,(int64_t)point)&&ring.present((uintptr_t)source,(int64_t)point+1))return true;}return false;}
 bool stems(const juce::AudioBuffer<float>* source,double point,int channel,std::array<float,4>& values,bool hq)const{auto* p=active.load(std::memory_order_acquire);if(!p)return false;for(auto& bank:p->banks){auto& ring=hq?bank.hq:bank.live;bool valid=true;for(int stem=0;stem<4;++stem)valid&=read(ring,(uintptr_t)source,point,stem*2+channel,values[stem]);if(valid)return true;}return false;}
};
